import type { ReactNode } from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { ChevronRightIcon } from "lucide-react"

import { cn } from "@humanctl/ui/lib/cn"

type ListRowProps = Omit<ButtonPrimitive.Props, "title"> & {
  title: ReactNode
  summary?: ReactNode
  metadata?: ReactNode
  leading?: ReactNode
  trailing?: ReactNode
  status?: ReactNode
  selected?: boolean
}

function ListRow({
  className,
  title,
  summary,
  metadata,
  leading,
  trailing,
  status,
  selected = false,
  ...props
}: ListRowProps) {
  return (
    <ButtonPrimitive
      data-slot="list-row"
      data-selected={selected || undefined}
      className={cn(
        "group/row grid min-h-[var(--row-task)] w-full grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 border-b border-border px-4 py-2 text-left outline-none transition-colors duration-[var(--duration-color)] hover:bg-[var(--overlay-hover)] focus-visible:bg-[var(--overlay-hover)] focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background data-[selected]:bg-[var(--overlay-selected)] disabled:pointer-events-none disabled:opacity-45",
        className,
      )}
      {...props}
    >
      {leading ? <span className="grid shrink-0 place-items-center text-ink-3">{leading}</span> : null}
      <span className="min-w-0">
        <span className="flex min-w-0 items-center gap-2">
          <span className="truncate text-[13px] leading-5 font-medium text-ink">{title}</span>
          {status}
        </span>
        {summary ? <span className="mt-0.5 block truncate text-[13px] leading-5 text-ink-2">{summary}</span> : null}
        {metadata ? <span className="mt-0.5 block truncate font-mono text-[11px] leading-4 text-ink-3">{metadata}</span> : null}
      </span>
      <span className="flex shrink-0 items-center gap-2">
        {trailing}
        <ChevronRightIcon className="size-3.5 text-ink-4 opacity-0 transition-opacity group-hover/row:opacity-100 group-focus-visible/row:opacity-100" />
      </span>
    </ButtonPrimitive>
  )
}

export { ListRow, type ListRowProps }

import type { ComponentProps } from "react"

import { cn } from "@humanctl/ui/lib/cn"

type StatusState = "running" | "needs-input" | "blocked" | "complete" | "idle"

const statusLabels: Record<StatusState, string> = {
  running: "Running",
  "needs-input": "Needs input",
  blocked: "Blocked",
  complete: "Complete",
  idle: "Idle",
}

const statusClasses: Record<StatusState, string> = {
  running: "bg-work-soft text-work before:bg-work",
  "needs-input": "bg-need-soft text-need before:bg-need",
  blocked: "bg-block-soft text-block before:bg-block",
  complete: "bg-done-soft text-done before:bg-done",
  idle: "bg-idle-soft text-idle before:bg-idle",
}

type StatusChipProps = ComponentProps<"span"> & {
  state: StatusState
  label?: string
}

function StatusChip({ state, label = statusLabels[state], className, ...props }: StatusChipProps) {
  return (
    <span
      data-slot="status-chip"
      data-state={state}
      className={cn(
        "inline-flex h-5 shrink-0 items-center gap-1.5 rounded-[var(--radius-1)] px-1.5 font-sans text-[11px] leading-none font-medium before:size-1.5 before:shrink-0 before:rounded-full",
        statusClasses[state],
        className,
      )}
      {...props}
    >
      {label}
    </span>
  )
}

export { StatusChip, type StatusChipProps, type StatusState }

import type { ComponentProps } from "react"

import { Progress, ProgressIndicator, ProgressLabel, ProgressTrack } from "@humanctl/ui/components/progress"
import { Skeleton } from "@humanctl/ui/components/skeleton"
import { cn } from "@humanctl/ui/lib/cn"

type QuotaRowProps = Omit<ComponentProps<typeof Progress>, "value" | "children"> & {
  label: string
  value?: number | null
  detail?: string
  reset?: string
  loading?: boolean
}

function QuotaRow({
  className,
  label,
  value,
  detail,
  reset,
  loading = false,
  ...props
}: QuotaRowProps) {
  const normalized = value == null ? null : Math.max(0, Math.min(100, value))

  return (
    <Progress
      data-slot="quota-row"
      value={normalized}
      showTrack={false}
      aria-label={`${label} quota`}
      aria-valuetext={normalized == null ? "Not available" : `${Math.round(normalized)} percent`}
      className={cn("grid min-h-[var(--row-decision)] grid-cols-[minmax(9rem,1fr)_minmax(8rem,1.4fr)_auto] items-center gap-4 border-b border-border px-4 py-2 max-[680px]:grid-cols-[1fr_auto]", className)}
      {...props}
    >
      <div className="min-w-0">
        <ProgressLabel className="block truncate text-ink">{label}</ProgressLabel>
        {reset ? <span className="block truncate font-mono text-[11px] text-ink-3">{reset}</span> : null}
      </div>
      {loading ? <Skeleton className="h-1 w-full max-[680px]:col-span-2" /> : <ProgressTrack className="max-[680px]:order-3 max-[680px]:col-span-2"><ProgressIndicator /></ProgressTrack>}
      <div className="min-w-16 text-right">
        {loading ? <Skeleton className="ml-auto h-4 w-12" /> : (
          <>
            <span className="font-mono text-[12px] tabular-nums text-ink">{normalized == null ? "N/A" : `${Math.round(normalized)}%`}</span>
            {detail ? <span className="ml-2 font-mono text-[11px] text-ink-3">{detail}</span> : null}
          </>
        )}
      </div>
    </Progress>
  )
}

export { QuotaRow, type QuotaRowProps }

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@humanctl/ui/lib/cn"

type FilterToolbarProps = ComponentProps<"div"> & {
  search?: ReactNode
  filters?: ReactNode
  actions?: ReactNode
  resultCount?: number
  resultLabel?: string
}

function FilterToolbar({
  className,
  search,
  filters,
  actions,
  resultCount,
  resultLabel = "results",
  ...props
}: FilterToolbarProps) {
  return (
    <div
      data-slot="filter-toolbar"
      className={cn(
        "flex min-h-[var(--toolbar)] shrink-0 items-center gap-2 border-b border-border px-3 py-1 max-[680px]:flex-wrap",
        className,
      )}
      {...props}
    >
      {search ? <div className="w-full max-w-72 min-w-40 max-[680px]:max-w-none">{search}</div> : null}
      {filters ? <div className="flex min-w-0 items-center gap-1.5">{filters}</div> : null}
      {resultCount != null ? (
        <span className="ml-1 whitespace-nowrap font-mono text-[11px] tabular-nums text-ink-3" aria-live="polite">
          {resultCount} {resultCount === 1 && resultLabel.endsWith("s") ? resultLabel.slice(0, -1) : resultLabel}
        </span>
      ) : null}
      {actions ? <div className="ml-auto flex shrink-0 items-center gap-1.5">{actions}</div> : null}
    </div>
  )
}

export { FilterToolbar, type FilterToolbarProps }
